mapper.delete:
DELETE FROM job_posting
WHERE jno = #{jno}
  AND cno = #{cno}

mapper.update:
UPDATE job_posting
SET jstatus = 'DELETED',
    jupdate = SYSDATE
WHERE jno = #{jno}
  AND cno = #{cno}

UPDATE job_posting
SET jstatus = 'APPROVED'
WHERE jno = #{value}

UPDATE job_posting
SET jstatus = 'REJECTED'
WHERE jno = #{value}

mapper.select:
SELECT COUNT(*) FROM job_posting j JOIN company c ON c.cno = j.cno
c.mno = #{mno}
AND ( j.jtitle LIKE '%'||#{q}||'%' OR j.jposition LIKE '%'||#{q}||'%' )
